void addOne(int x) {
    x = x + 1;
}

int main() {
    int n = 5;
    addOne(n);
    // n is still 5
}

void addOne(int& x) {
    x = x + 1;
}

int main() {
    int n = 5;
    addOne(n);
    // n is now 6
}

void addOne(int* x) {
    *x = *x + 1;
}

int main() {
    int n = 5;
    addOne(&n);
    // n is now 6
}
